/**
 * Fixtures for the application's unit tests: a configuration with two layouts and an
 * authentication contract the test drives. Generated by forge.
 */
import { defineComponent, h, ref } from 'vue'
import { createMemoryHistory, createRouter, type RouteRecordRaw, type Router } from 'vue-router'
import type { ApplicationConfig, AuthContract, MenuItemConfig } from './contracts'

export function testApplication(overrides: Partial<ApplicationConfig> = {}): ApplicationConfig {
  return {
    title: 'Test app',
    auth: true,
    routing: { landing: 'start', sign_in: 'login', not_found: 'not-found', auth_stuck: 'auth-stuck', forbidden: 'forbidden' },
    builtin: [],
    layouts: {
      main: {
        shell: 'header-sidebar',
        placeholder: 'not-built',
        menus: {
          primary: [
            { items: [
              { id: 'start', label: 'Start', icon: 'i-lucide-house', to: 'start' },
              { id: 'sales', label: 'Sales', children: [
                { id: 'orders', label: 'Orders', to: 'orders' },
                { id: 'invoices', label: 'Invoices', badge: 'invoices' },
              ] },
            ] },
            { label: 'More', items: [{ id: 'help', label: 'Help', action: 'help' }] },
          ],
          account: [{ items: [{ id: 'sign-out', label: 'Log out', action: 'sign-out' }] }],
          footer: [{ items: [{ id: 'support', label: 'Support' }] }],
        },
      },
      staff: { shell: 'header-sidebar', placeholder: null, menus: { primary: [{ items: [{ id: 'audit', label: 'Audit' }] }], account: [], footer: [] } },
    },
    extras: [],
    ...overrides,
  }
}

export function testAuth(signedIn = true, roles: string[] = []) {
  const isAuthenticated = ref(signedIn)
  const isLoading = ref(false)
  const user = ref<unknown>(signedIn ? { username: 'dev' } : null)
  const calls: string[] = []
  const auth: AuthContract = {
    isAuthenticated,
    isLoading,
    user,
    hasRole: role => roles.includes(role),
    signIn: (redirect) => {
      calls.push(`signIn:${redirect ?? ''}`)
    },
    signOut: () => {
      calls.push('signOut')
    },
  }
  return { auth, isAuthenticated, isLoading, user, calls }
}

const Blank = defineComponent({ name: 'BlankPage', setup: () => () => h('div', { 'data-test': 'blank-page' }) })

function targets(items: MenuItemConfig[]): string[] {
  return items.flatMap(item => [...(item.to ? [item.to] : []), ...targets(item.children ?? [])])
}

/** A router with a page for every route the configuration names, for mounting a component that links to them. */
export async function routerFor(config: ApplicationConfig, at = '/'): Promise<Router> {
  const names = new Set<string>(Object.values(config.routing).filter((name): name is string => Boolean(name)))
  for (const layout of Object.values(config.layouts)) {
    for (const sections of Object.values(layout.menus)) for (const name of targets(sections.flatMap(section => section.items))) names.add(name)
  }
  const routes: RouteRecordRaw[] = [...names].map(name => ({ path: `/${name}`, name, component: Blank }))
  for (const layout of Object.values(config.layouts)) {
    if (layout.placeholder) routes.push({ path: `/${layout.placeholder}/:item`, name: layout.placeholder, component: Blank })
  }
  routes.push({ path: '/:any(.*)*', name: '__fallback__', component: Blank })
  const router = createRouter({ history: createMemoryHistory(), routes })
  await router.push(at)
  await router.isReady()
  return router
}
